// GrinKingdom — species database (1,000 species).
// CURATED: 48 hand-written "flagship" entries (species-curated.js).
// EXTRA_SPECIES: generated by scripts/gen-species.mjs from the seed lists
// in scripts/seeds/ (run `npm run gen` after changing seeds).
import { CURATED } from './species-curated.js'
import { EXTRA_SPECIES } from './species-extra.js'

export const SPECIES = [...CURATED, ...EXTRA_SPECIES]

export const SPECIES_MAP = Object.fromEntries(SPECIES.map((s) => [s.slug, s]))

export const speciesByKingdom = (kingdomId) => SPECIES.filter((s) => s.kingdom === kingdomId)

/* Illustration URL for a species card/detail photo (build-time generated SVG art). */
export const speciesImage = (slug) => `${import.meta.env.BASE_URL}images/species/${slug}.svg`

// Distinct values for the Explore filter chips (in data order).
const distinct = (key) => [...new Set(SPECIES.map((s) => s[key]))]
export const HABITATS = distinct('habitat')
export const DIETS = distinct('diet')
export const STATUSES = distinct('status')
